package abisal;

import javax.microedition.m3g.Image2D;
import javax.microedition.m3g.Texture2D;

/**
 * Original textures generated by code at startup (no image files). They are mostly
 * light grey detail maps: the GE multiplies them by the lit vertex colour, so one texture
 * works for every biome (sand, moss, red rock...) and only adds grain and relief.
 * All of them tile seamlessly (the noise wraps around the edges).
 */
public final class Texturas {
    static final int T = 64;
    private static Texture2D suelo;
    private static Texture2D roca;
    private static Texture2D metal;

    private Texturas() {
    }

    /** periodic value noise in [0,1]: repeats every 'per' cells, so the texture tiles */
    private static float ruidoP(float x, float y, int per, int s) {
        int ix = j2me.FMath.floor(x);
        int iy = j2me.FMath.floor(y);
        float fx = x - ix;
        float fy = y - iy;
        fx = fx * fx * (3 - 2 * fx);
        fy = fy * fy * (3 - 2 * fy);
        int x0 = ((ix % per) + per) % per, x1 = (x0 + 1) % per;
        int y0 = ((iy % per) + per) % per, y1 = (y0 + 1) % per;
        float a = Terreno.azar(x0, y0, s);
        float b = Terreno.azar(x1, y0, s);
        float c = Terreno.azar(x0, y1, s);
        float d = Terreno.azar(x1, y1, s);
        return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
    }

    /** sea floor detail: fine grain, small pebbles and soft ripples */
    static Texture2D suelo() {
        if (suelo != null) {
            return suelo;
        }
        long t0 = System.currentTimeMillis();
        byte[] px = new byte[T * T * 3];
        for (int y = 0; y < T; y++) {
            for (int x = 0; x < T; x++) {
                float u = (float) x / T;
                float v = (float) y / T;
                // broad blotches + medium grain + fine grain
                float n = ruidoP(u * 4, v * 4, 4, 71) * 0.45f + ruidoP(u * 16, v * 16, 16, 72) * 0.35f
                        + Terreno.azar(x, y, 73) * 0.2f;
                // soft ripples running across the tile (period divides the size: seamless)
                float onda = j2me.FMath.sin((u + ruidoP(u * 2, v * 2, 2, 74) * 0.15f) * 6.2831855f * 3) * 0.5f + 0.5f;
                float l = 0.72f + n * 0.22f + onda * 0.06f;
                // scattered pebbles: darker specks
                if (Terreno.azar(x, y, 75) > 0.985f) {
                    l *= 0.7f;
                }
                int c = (int) (l * 255);
                c = c > 255 ? 255 : c;
                int o = (y * T + x) * 3;
                px[o] = (byte) c;
                px[o + 1] = (byte) c;
                px[o + 2] = (byte) (c * 0.97f);
            }
        }
        Image2D img = new Image2D(Image2D.RGB, T, T, px);
        suelo = new Texture2D(img);
        suelo.setWrapping(Texture2D.WRAP_REPEAT, Texture2D.WRAP_REPEAT);
        suelo.setFiltering(Texture2D.FILTER_BASE_LEVEL, Texture2D.FILTER_LINEAR);
        suelo.setBlending(Texture2D.FUNC_MODULATE);
        Log.d("textura del suelo generada (" + T + "x" + T + ") en " + (System.currentTimeMillis() - t0) + " ms");
        return suelo;
    }

    /** rock detail: mottled stone with dark cracks and pale mineral flecks */
    static Texture2D roca() {
        if (roca != null) {
            return roca;
        }
        long t0 = System.currentTimeMillis();
        byte[] px = new byte[T * T * 3];
        for (int y = 0; y < T; y++) {
            for (int x = 0; x < T; x++) {
                float u = (float) x / T;
                float v = (float) y / T;
                float n = ruidoP(u * 3, v * 3, 3, 81) * 0.5f + ruidoP(u * 8, v * 8, 8, 82) * 0.3f
                        + Terreno.azar(x, y, 83) * 0.2f;
                float l = 0.62f + n * 0.34f;
                // cracks: thin dark lines where a second noise field crosses 0.5
                float g = ruidoP(u * 5, v * 5, 5, 84);
                float d = Math.abs(g - 0.5f);
                if (d < 0.025f) {
                    l *= 0.55f + d * 10;
                }
                if (Terreno.azar(x, y, 85) > 0.99f) {
                    l = Math.min(1, l * 1.25f); // mineral flecks
                }
                int c = (int) (l * 255);
                c = c > 255 ? 255 : c;
                int o = (y * T + x) * 3;
                px[o] = (byte) c;
                px[o + 1] = (byte) (c * 0.98f);
                px[o + 2] = (byte) (c * 0.95f);
            }
        }
        roca = new Texture2D(new Image2D(Image2D.RGB, T, T, px));
        roca.setWrapping(Texture2D.WRAP_REPEAT, Texture2D.WRAP_REPEAT);
        roca.setFiltering(Texture2D.FILTER_BASE_LEVEL, Texture2D.FILTER_LINEAR);
        roca.setBlending(Texture2D.FUNC_MODULATE);
        Log.d("textura de roca generada (" + T + "x" + T + ") en " + (System.currentTimeMillis() - t0) + " ms");
        return roca;
    }

    /** brushed metal: fine streaks along one axis with a few scratches (tool blades) */
    static Texture2D metal() {
        if (metal != null) {
            return metal;
        }
        byte[] px = new byte[T * T * 3];
        for (int y = 0; y < T; y++) {
            float fila = Terreno.azar(0, y, 91);
            for (int x = 0; x < T; x++) {
                float l = 0.78f + fila * 0.12f + Terreno.azar(x, y, 92) * 0.06f
                        + ruidoP((float) x / T * 2, (float) y / T * 2, 2, 93) * 0.06f;
                if (Terreno.azar(x / 3, y, 94) > 0.985f) {
                    l = 1; // scratch
                }
                int c = (int) (Math.min(1, l) * 255);
                int o = (y * T + x) * 3;
                px[o] = (byte) (c * 0.96f);
                px[o + 1] = (byte) c;
                px[o + 2] = (byte) c;
            }
        }
        metal = new Texture2D(new Image2D(Image2D.RGB, T, T, px));
        metal.setWrapping(Texture2D.WRAP_REPEAT, Texture2D.WRAP_REPEAT);
        metal.setFiltering(Texture2D.FILTER_BASE_LEVEL, Texture2D.FILTER_LINEAR);
        metal.setBlending(Texture2D.FUNC_MODULATE);
        return metal;
    }
}
